// Runs only in the disposable extension generated by scripts/e2e-firefox.mjs.
// Never included in either store package. No WebDriver privileged-scope access.
import { api, isExtensionUrl } from '../src/browser-api.js';
import { defaultAwsSettings } from '../src/aws.js';
import { defaultCloseSettings } from '../src/age-closer.js';
import { createStorage } from '../src/storage.js';
import { addLogEntry } from '../src/log.js';
import { runSecurityChecks } from './security-browser.js';

const { origin } = await (await fetch(api.runtime.getURL('help/test-config.json'))).json();
const post = (path, body) => fetch(origin + path, { method: 'POST', body: JSON.stringify(body) });
async function check(value, message) {
  if (!value) throw new Error(message);
  await post('/progress', { message: `  ok  ${message}` });
}
const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));
async function until(fn, message, timeout = 12_000) {
  const start = Date.now();
  while (Date.now() - start < timeout) {
    const value = await fn();
    if (value) return value;
    await sleep(100);
  }
  const detail = message === 'status group' ? {
    groups: await api.tabGroups.query({}), permissions: await api.permissions.getAll(),
    test: await send({ type: 'group-test', tabId: (await api.tabs.query({})).find((tab) => tab.url.includes('/ticket/'))?.id,
      rule: (await api.storage.sync.get('grule:ff-group'))['grule:ff-group'] }),
  } : null;
  throw new Error(`Timed out: ${message}${detail ? '\n' + JSON.stringify(detail) : ''}`);
}
const send = (message) => api.runtime.sendMessage(message);
const pending = async () => (await api.storage.session.get('pending')).pending ?? {};
const groupTitle = async (id) => (await api.tabGroups.get(id)).title;
const makeTab = (path) => api.tabs.create({ url: origin + path, active: false });
try {
  await until(() => document.getElementById('pause-select')?.options.length > 0, 'settings initialized');
  await check(typeof api.tabGroups?.move === 'function', 'Firefox exposes native grouping APIs');
  await check(document.getElementById('privacy-details').textContent.includes('Firefox Sync'), 'popup privacy wording uses Firefox Sync');
  await check(isExtensionUrl(location.href, api.runtime.getURL('')), 'extension page identity uses its moz-extension URL');
  await check((await send({ type: 'version' })).ok, 'settings page can send trusted worker messages');
  const old = await makeTab('/age-check');
  const oldCreated = Date.now();

  await api.storage.sync.set({ 'rule:ff-close': {
    id: 'ff-close', name: 'Firefox close', enabled: true, title: null,
    url: { mode: 'contains', pattern: '/close-me', caseSensitive: false },
    delaySeconds: 2, groupAfterSeconds: 0, createdAt: Date.now(),
  }, ruleOrder: ['ff-close'] });
  await sleep(250);
  const kept = await makeTab('/close-me?title=Keep');
  await until(async () => (await pending())[kept.id], 'pending close');
  const closingGroup = await until(async () => {
    const tab = await api.tabs.get(kept.id);
    return tab.groupId !== -1 ? api.tabGroups.get(tab.groupId) : null;
  }, 'Closing group');
  await check(closingGroup.title === 'Closing' && closingGroup.color === 'red', 'pending tabs enter the red Closing group');
  await send({ type: 'cancel', tabId: kept.id, keep: true });
  await sleep(2300);
  await check(Boolean(await api.tabs.get(kept.id)), 'Keep prevents the scheduled close');
  await check((await api.tabs.get(kept.id)).groupId === -1, 'Keep restores the tab outside Closing');
  const closed = await makeTab('/close-me?title=Close');
  await until(async () => !(await api.tabs.query({})).some((tab) => tab.id === closed.id), 'matching close');
  await check((await api.storage.local.get('log')).log.some((entry) => entry.url.endsWith('/close-me') && !entry.url.includes('?')), 'actual closes are logged without URL queries');
  const pinned = await api.tabs.create({ url: origin + '/close-me?pinned=1', pinned: true, active: false });
  await sleep(2300);
  await check(Boolean(await api.tabs.get(pinned.id)) && !(await pending())[pinned.id], 'pinned matching tab is protected');

  await api.storage.sync.set({ 'grule:ff-group': {
    id: 'ff-group', name: 'Firefox tickets', enabled: true,
    regex: '/ticket/([A-Z]+-[0-9]+)', titleTemplate: '$1', color: 'blue', colorMode: 'fixed',
    statusEnabled: true, statusFields: [{ selector: '#status', keepOnly: '', label: '' }],
    siteOrigin: origin, createdAt: Date.now(),
  }, groupRuleOrder: ['ff-group'] });
  await sleep(250);
  const ticket = await makeTab('/ticket/FX-1?status=To%20Do');
  const ticketGroup = await until(async () => {
    const tab = await api.tabs.get(ticket.id);
    return tab.groupId !== -1 && (await groupTitle(tab.groupId)) === 'FX-1 - To Do' ? tab.groupId : null;
  }, 'status group');
  await check(Boolean(ticketGroup), 'URL capture and initial page status name the group');
  await api.scripting.executeScript({ target: { tabId: ticket.id }, func: () => {
    document.getElementById('status').textContent = 'Done';
  } });
  await until(async () => (await groupTitle(ticketGroup)) === 'FX-1 - Done', 'live status');
  await check(true, 'injected reader updates the Firefox group title live');
  const beforeLimit = (await api.storage.local.get('maxTitleLength')).maxTitleLength;
  await api.scripting.executeScript({ target: { tabId: ticket.id }, func: async () => {
    await browser.runtime.sendMessage({ type: 'set-title-limit', limit: 12 }).catch(() => {});
  } });
  await check((await api.storage.local.get('maxTitleLength')).maxTitleLength === beforeLimit,
    'page readers cannot invoke settings-only messages');
  const tested = await send({ type: 'group-test', tabId: ticket.id, rule: {
    regex: '/ticket/([A-Z]+-[0-9]+)', titleTemplate: '$1', color: 'blue', colorMode: 'fixed',
    statusEnabled: true, statusFields: [{ selector: '#status', keepOnly: '', label: '' }], siteOrigin: origin,
  } });
  await check(tested.ok && tested.status === 'Done', 'group Test reads status from Firefox frames');

  const settings = { ...defaultAwsSettings(), enabled: true, urlPattern: '/aws' };
  await api.storage.sync.set({ awsSettings: settings });
  await sleep(250);
  const aws = await makeTab('/aws?region=us-west-2');
  await until(async () => {
    const tab = await api.tabs.get(aws.id);
    return tab.groupId !== -1 && (await groupTitle(tab.groupId)) === 'Acme Dev · AdminRole';
  }, 'AWS group');
  const awsTest = await send({ type: 'aws-test', tabId: aws.id, settings });
  await check(awsTest.ok && awsTest.info.accountId === '123456789012' && awsTest.info.region === 'us-west-2',
    'AWS navigation labels and URL region are read in Firefox');

  for (const [role, expectedRole] of [['root', 'root'], ['Recently visited', '']]) {
    const tab = await makeTab(`/aws?region=us-west-2&role=${encodeURIComponent(role)}`);
    const expectedTitle = expectedRole ? `Acme Dev · ${expectedRole}` : 'Acme Dev';
    await until(async () => {
      const current = await api.tabs.get(tab.id);
      return current.groupId !== -1 && (await groupTitle(current.groupId)) === expectedTitle;
    }, `AWS identity ${role}`);
    const testedIdentity = await send({ type: 'aws-test', tabId: tab.id, settings });
    await check(testedIdentity.ok && testedIdentity.info.role === expectedRole && testedIdentity.info.user === '',
      role === 'root' ? 'AWS root session is recognized in Firefox' : 'AWS unmatched navigation text is excluded from Firefox group titles');
  }

  // Exercise real options-page CRUD without a native permission prompt.
  document.getElementById('tab-group').click();
  document.getElementById('add-group-rule').click();
  await until(() => !document.getElementById('group-form-section').hidden, 'group form');
  const fields = document.getElementById('group-form').elements;
  fields.name.value = 'UI Firefox rule'; fields.regex.value = '/ui-only'; fields.titleTemplate.value = 'UI';
  fields.statusEnabled.checked = true; fields.siteOrigin.value = origin;
  fields.siteOrigin.dispatchEvent(new Event('input', { bubbles: true }));
  await check(document.getElementById('group-permission-save').textContent.includes('http://127.0.0.1/*'),
    'Firefox permission disclosure shows the host pattern without its unsupported port');
  fields.statusEnabled.checked = false;
  fields.statusEnabled.dispatchEvent(new Event('input', { bubbles: true }));
  document.getElementById('save-group-rule').click();
  await until(async () => Object.values(await api.storage.sync.get(null)).some((value) => value?.name === 'UI Firefox rule'), 'UI save');
  await check(true, 'Firefox settings UI saves a grouping rule through storage');
  document.getElementById('aws-settings').click();
  await check(document.getElementById('aws-settings').textContent === 'Access instructions' &&
    document.getElementById('aws-status').textContent.includes('Add-ons and themes'),
    'Firefox shows access instructions instead of a blocked privileged settings link');

  await api.storage.sync.set({ 'rule:ff-race': {
    id: 'ff-race', name: 'Firefox race', enabled: true, title: null,
    url: { mode: 'contains', pattern: '/race-close/', caseSensitive: false },
    delaySeconds: 1, createdAt: Date.now(),
  }, ruleOrder: ['ff-close', 'ff-race'] });
  await sleep(250);
  const storage = createStorage(api.storage);
  await Promise.all([
    Promise.all(Array.from({ length: 10 }, (_, index) => makeTab('/race-close/' + index))),
    Promise.all(Array.from({ length: 10 }, (_, index) => addLogEntry(storage, {
      title: 'UI race ' + index, url: origin + '/ui-race/' + index,
      ruleId: 'ff-race', ruleName: 'Firefox race', closedAt: Date.now(),
    }))),
  ]);
  await until(async () => (await api.storage.local.get('log')).log.filter((entry) => entry.ruleId === 'ff-race').length === 20,
    'concurrent Firefox close history');
  await check(true, 'Firefox background and settings preserve all 20 concurrent history writes');

  // Exercise a real long grouping alarm while leaving the event page idle.
  for (const message of await runSecurityChecks({ origin, tabId: ticket.id })) await check(true, message);
  await api.storage.sync.set({ 'rule:ff-alarm': {
    id: 'ff-alarm', name: 'Firefox alarm', enabled: true, title: null,
    url: { mode: 'contains', pattern: '/alarm-check', caseSensitive: false },
    delaySeconds: 90, groupAfterSeconds: 35, createdAt: Date.now(),
  }, ruleOrder: ['ff-close', 'ff-alarm'] });
  await sleep(250);
  const alarmTab = await makeTab('/alarm-check');
  await until(async () => (await pending())[alarmTab.id], 'long grouping pending');
  await check((await api.tabs.get(alarmTab.id)).groupId === -1, 'long grouping grace initially keeps the tab in place');
  await until(async () => (await api.tabs.get(alarmTab.id)).groupId !== -1, 'Firefox grouping alarm', 45_000);
  await check(true, 'Firefox alarm groups the tab after a long quiet grace period');
  await send({ type: 'cancel', tabId: alarmTab.id, keep: true });

  await api.storage.sync.set({ closeSettings: { ...defaultCloseSettings(), maxOpen: { enabled: true, value: 1, unit: 'minutes' } } });
  await sleep(Math.max(300, oldCreated + 61_000 - Date.now()));
  const sweep = await send({ type: 'sweep' });
  await until(async () => !(await api.tabs.query({})).some((tab) => tab.id === old.id), 'age sweep closes old tab');
  await check(sweep.ok && Boolean(await api.tabs.get(pinned.id)), 'Firefox age sweep closes an old tab while keeping pinned tabs');

  const permissionTab = await makeTab('/ticket/FX-999?status=Denied');
  await until(async () => {
    const tab = await api.tabs.get(permissionTab.id);
    return tab.url.startsWith(origin + '/ticket/FX-999') && tab.status === 'complete';
  }, 'permission fixture loaded');
  await api.permissions.remove({ origins: ['http://127.0.0.1/*'] });
  const denied = await send({ type: 'group-test', tabId: permissionTab.id, rule: {
    regex: '/ticket/([A-Z]+-[0-9]+)', titleTemplate: '$1', color: 'blue', colorMode: 'fixed',
    statusEnabled: true, statusFields: [{ selector: '#status', keepOnly: '', label: '' }], siteOrigin: origin,
  } });
  if (!denied.ok || denied.error !== 'access-not-granted') {
    throw new Error(`Revoked host permission must prevent new page reads: ${JSON.stringify(denied)}`);
  }
  // Navigation can report success after removing the extension's fetch grant.
  await api.tabs.create({ url: origin + '/passed', active: false });
} catch (error) {
  await post('/result', { ok: false, error: `${error.message}\n${error.stack}` }).catch(() =>
    api.tabs.create({ url: origin + '/failed?error=' + encodeURIComponent(error.message), active: false }));
}
